Response: documented from billing-service PUT /v1/brands/{brandId}/offers/{offerId}/sales-funnels/{salesFunnelId}/caps, which owns it; the gateway forwards it unchanged.","params":[{"name":"brandId","in":"path","required":true,"description":"Brand ID","type":"string"},{"name":"offerId","in":"path","required":true,"description":"Offer ID","type":"string"},{"name":"salesFunnelId","in":"path","required":true,"description":"features-service sales funnel id (its combinationKey), URL-encoded","type":"string"}],"body":{"type":"object","properties":{"maxBudget":{"type":"object","nullable":true,"properties":{"amountCents":{"anyOf":[{"type":"string"},{"type":"number"}]},"period":{"type":"string","enum":["one_off","daily","weekly","monthly"],"description":"UTC. daily = the calendar day; weekly = Monday 00:00 to the next Monday; monthly = the calendar month; one_off = once, counted from when the cap was first stated in this period (never resets)."}},"required":["amountCents","period"],"additionalProperties":false},"maxVolume":{"type":"object","nullable":true,"properties":{"count":{"type":"integer","minimum":0},"period":{"type":"string","enum":["one_off","daily","weekly","monthly"],"description":"UTC. daily = the calendar day; weekly = Monday 00:00 to the next Monday; monthly = the calendar month; one_off = once, counted from when the cap was first stated in this period (never resets)."}},"required":["count","period"],"additionalProperties":false}},"required":["maxBudget","maxVolume"],"additionalProperties":false,"description":"Both keys are REQUIRED: an object states the cap, null clears it; both null clears the funnel. A cap restated in the same period keeps its window start (a one_off cap keeps counting)."},"answers":[{"status":"200","description":"Billing's read (caps, consumed, remaining, reached), forwarded untouched","schema":{"truncated":true,"firstChars":"{"type":"object","properties":{"orgId":{"type":"string","format":"uuid"},"brandId":{"type":"string","format":"uuid"}